  "Benar. Skor {n}": ["Correct. Score {n}", "正解。スコア {n}", "정답. 점수 {n}"],
  "{a} dari {b} prajurit bangkit.": ["{a} of {b} soldiers have risen.", "{b}人中{a}人の兵士が目覚めた。", "병사 {b}명 중 {a}명이 깨어났습니다."],
  "Taklukkan dungeon untuk merekrut prajurit baru.": ["Conquer dungeons to recruit new soldiers.", "ダンジョンを攻略して新しい兵士を仲間にしよう。", "던전을 정복해 새 병사를 영입하세요."],
